using System.IO;
namespace Ansary;
public sealed record IndexedHit(string Path,int Index,string Text,long Length,long Ticks);
public sealed class DocumentStore {
 readonly DocumentCache memory=new();
 public DocumentSnapshot Get(string path)=>memory.Get(path);
 public List<IndexedHit> Search(string path,string[] words,CancellationToken token){token.ThrowIfCancellationRequested();var doc=memory.Get(path);var hits=new List<IndexedHit>();for(int i=0;i<doc.Paragraphs.Length;i++){token.ThrowIfCancellationRequested();if(Core.Match(doc.Paragraphs[i],words))hits.Add(new IndexedHit(doc.Path,i,doc.Paragraphs[i],doc.Length,doc.Ticks));}return hits;}
 public static void Verify(){string dir=Path.Combine(Path.GetTempPath(),"AnsaryDirect-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string file=Path.Combine(dir,"test.docx");using(var z=System.IO.Compression.ZipFile.Open(file,System.IO.Compression.ZipArchiveMode.Create)){using var w=new StreamWriter(z.CreateEntry("word/document.xml").Open());w.Write("<w:document xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'><w:body><w:p><w:r><w:t>بحث عربي سريع في المكتبة ABCDE</w:t></w:r></w:p><w:p><w:r><w:t>النتائج هنا في المكتبة</w:t></w:r></w:p></w:body></w:document>");}var store=new DocumentStore();foreach(string query in new[]{"بحث سريع","في","\"في المكتبة\"","bcd","غيرموجود","عربي بحث"}){var terms=Core.Terms(query);var expected=Core.Read(file).Select((t,i)=>(t,i)).Where(x=>Core.Match(x.t,terms)).Select(x=>x.i);if(!expected.SequenceEqual(store.Search(file,terms,CancellationToken.None).Select(h=>h.Index)))throw new InvalidDataException("Direct search parity failed");}if(!ReferenceEquals(store.Get(file),store.Get(file))||Directory.GetFiles(dir,"*.db").Length!=0)throw new InvalidOperationException("Direct cache regression");}finally{Directory.Delete(dir,true);}}
}
